parameters.jsCode:
// ===============================
// GET DATA FROM PREVIOUS NODES
// ===============================

// Invoice extracted by AI (from Basic LLM Chain)
const invoice = $node["Clean Extracted Fields"].json;

// PO fetched from Google Sheet (previous node)
const poRow = $node["Search ERP for PO"].json;


// ===============================
// NORMALIZE PO DATA FROM SHEET
// ===============================

const po = poRow && poRow.po_number
  ? {
      po_number: poRow.po_number,
      supplier_name: poRow.supplier_name,
      currency: poRow.currency,
      total_amount: Number(poRow.total_amount),
      status: poRow.status
    }
  : null;


// ===============================
// INVOICE READINESS VALIDATION
// ===============================

let issues = [];
let status = "APPROVED";


// --- RULE 1: PO MUST EXIST ---
if (!po) {
  status = "REJECTED";
  issues.push("PO not found in Purchase Order database");
}


// --- RULE 2: PO NUMBER MUST MATCH ---
if (po && invoice.po_number !== po.po_number) {
  status = "REJECTED";
  issues.push("Invoice PO number does not match any approved PO");
}


// --- RULE 3: SUPPLIER NAME MUST MATCH PO ---
if (po && invoice.supplier_name !== po.supplier_name) {
  status = "FLAGGED";
  issues.push("Supplier mismatch between Invoice and PO");
}


// --- RULE 4: AMOUNT SHOULD MATCH PO ---
if (po && Number(invoice.total_amount) !== Number(po.total_amount)) {
  status = "FLAGGED";
  issues.push("Invoice amount differs from PO amount");
}


// --- RULE 5: CURRENCY SHOULD MATCH ---
// --- HELPER: Normalize currency ---
function normalizeCurrency(cur) {
  if (!cur) return "";

  cur = cur.toString().toUpperCase();

  if (cur.includes("INR") || cur.includes("₹") || cur.includes("RS")) return "INR";
  if (cur.includes("USD") || cur.includes("$")) return "USD";
  if (cur.includes("EUR") || cur.includes("€")) return "EUR";
  if (cur.includes("GBP") || cur.includes("£")) return "GBP";

  return cur.trim();
}

// --- RULE: CURRENCY MATCH ---
if (po && normalizeCurrency(invoice.currency) !== normalizeCurrency(po.currency)) {
  status = "FLAGGED";
  issues.push("Currency mismatch between Invoice and PO");
}

// --- RULE 6: PO MUST BE APPROVED ---
if (po && po.status !== "Approved") {
  status = "FLAGGED";
  issues.push("PO exists but is not approved yet");
}


// --- RULE 7: DELIVERY PROOF (GRN) MUST EXIST ON INVOICE ---
if (!invoice.grn_number) {
  status = "FLAGGED";
  issues.push("Invoice missing GRN (proof of delivery)");
}


// ===============================
// FINAL OUTPUT FOR NEXT NODES
// ===============================

return [
  {
    json: {
      status,        // APPROVED | FLAGGED | REJECTED
      issues,        // list of problems
      invoice,       // extracted invoice data
      po             // matched PO data
    }
  }
];

