parameters.jsCode:
const item = $json;
let errors = [];

// 1. Check for missing critical fields from the merge
if (!item.po_number) errors.push("Missing PO Number");
if (!item.supplier_name) errors.push("Missing Supplier Name");
if (!item.total_amount || Number(item.total_amount) <= 0) {
  errors.push("Invalid or Zero Amount");
}

// 2. Check the ERP Status
// If the PO isn't "Approved" in your sheet, we shouldn't process the invoice
if (item.status !== "Approved") {
  errors.push(`PO Status is ${item.status || 'Unknown'} (Expected: Approved)`);
}

// 3. Finalize Status
item.validation_status = errors.length > 0 ? "INVALID" : "VALID";
item.validation_errors = errors.join(", ");

return [{ json: item }];

