                <tr><td>Invoice Number</td><td>{{ $('3-Way Match Validator').item.json.invoice.invoice_number }}</td></tr>
                <tr><td>Supplier</td>{{ $('3-Way Match Validator').item.json.invoice.supplier_name }}<td></td></tr>
                <tr><td>Amount</td>{{ $('3-Way Match Validator').item.json.invoice.total_amount }}<td></td></tr>
                <tr><td>PO Number</td><td>{{ $('3-Way Match Validator').item.json.invoice.po_number }}</td></tr>
            </table>

            <h3 style="font-size: 15px; margin-bottom: 8px;">Detection Summary & AI Reasoning:</h3>
            <div class="issue-box" style="border-left: 4px solid #1e40af; color: #b91c1c;">
                {{ $json.output.reason }}
            </div>

            <p style="margin-top: 25px;">Please verify these details in the <strong>Exception_Invoices</strong> sheet before proceeding with approval.</p>
        </div>
        <div class="footer">
            Generated by Invoice Validation Bot &bull; Timestamp: {{ $now }}
        </div>
    </div>
</body>
</html>
